const mapNavItems = (items: INavItem[]): NavItem[] =>
  items.map(({ name, link, status, isUpdate, links }) => ({
    name,
    href: link || undefined,
    isVisible: status,
    isUpdate,
    items: links?.length ? mapNavItems(links) : undefined,
  }));

